mapper.select:
SELECT STRFTIME('%Y-%m-%d %H:%M:%S', C.REG_DATE) AS regDate, STRFTIME('%Y-%m-%d %H:%M:%S', C.UPDATE_DATE) AS updateDate, C.COMMENT_NO AS commentNo, C.UID AS uid, C.IS_DELETED AS deleted, C.FRAGMENT_NO AS fragmentNo, F.UID AS fragmentUid, SUBSTR(F.CONTENT, 1, 80) AS fragmentContent, F.TOPIC_NO AS topicNo, T.NAME AS topicName, C.USER_NO AS userNo, U.ID AS userId, U.NICKNAME AS userNickname, C.CONTENT AS content FROM MB_FRAGMENT_COMMENTS C INNER JOIN MB_FRAGMENT F ON F.FRAGMENT_NO = C.FRAGMENT_NO INNER JOIN MB_TOPIC T ON T.TOPIC_NO = F.TOPIC_NO INNER JOIN MB_USER U ON U.USER_NO = C.USER_NO WHERE STRFTIME('%Y-%m-%d', C.REG_DATE) = #{date}
AND ( UPPER(C.CONTENT) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(C.UID) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(U.ID) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(U.NICKNAME) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(T.NAME) LIKE '%' || UPPER(#{keyword}) || '%' OR UPPER(F.CONTENT) LIKE '%' || UPPER(#{keyword}) || '%' )
ORDER BY C.COMMENT_NO DESC LIMIT 20 OFFSET #{offset}
